/* Língua Portuguesa — 10 itens inéditos por subtópico do Edital PRF nº 1/2021 (5 C + 5 E cada). Parte A: tópicos 1 a 5.5. */
(function () {
  var D = 'Língua Portuguesa', n = 0;
  function q(topico, tema, gabarito, enunciado, comentario) {
    n++;
    return { id: 'LP-' + String(n).padStart(3, '0'), disciplina: D, tema: tema, topico: topico,
             gabarito: gabarito, enunciado: enunciado, comentario: comentario };
  }
  var T1 = '1 Compreensão e interpretação de textos', M1 = 'Interpretação de textos';
  var T2 = '2 Tipos e gêneros textuais', M2 = 'Tipologia e gêneros';
  var T3 = '3 Ortografia oficial', M3 = 'Ortografia';
  var T41 = '4.1 Referenciação, substituição, repetição e conectores', T42 = '4.2 Tempos e modos verbais', M4 = 'Coesão textual';
  var T51 = '5.1 Classes de palavras', T52 = '5.2 Coordenação', T53 = '5.3 Subordinação', M5 = 'Morfossintaxe';
  var T54 = '5.4 Pontuação', M54 = 'Pontuação';
  var T55 = '5.5 Concordância verbal e nominal', M55 = 'Concordância e regência';

  var TX1 = '“A fiscalização eletrônica de velocidade costuma ser criticada como mecanismo arrecadatório. Contudo, levantamentos feitos em diversas rodovias indicam redução expressiva de acidentes graves nos trechos monitorados. O objetivo principal da medida, portanto, não é multar, mas induzir o condutor a respeitar o limite antes mesmo de ser autuado.”';
  var TX2 = '“O uso do cinto de segurança no banco traseiro ainda é negligenciado por muitos passageiros. Em uma colisão frontal, o ocupante sem cinto pode ser projetado contra o banco dianteiro, ferindo também quem está à frente. Trata-se, portanto, de uma proteção coletiva, e não apenas individual.”';
  var TX3 = '“Rodovias bem sinalizadas reduzem a incerteza do motorista. Placas legíveis, faixas visíveis à noite e informações antecipadas sobre curvas permitem decisões mais seguras. Ainda assim, nenhuma sinalização substitui a atenção de quem dirige.”';
  var TX4 = '“O transporte de cargas pelas rodovias federais movimenta grande parte da economia nacional. Quando uma ponte é interditada, os efeitos ultrapassam o trânsito local: atrasam entregas, encarecem fretes e afetam o abastecimento de cidades distantes.”';

  window.QUESTOES = (window.QUESTOES || []).concat([
    /* ===== 1 Compreensão e interpretação de textos ===== */
    q(T1, M1, 'C', 'Texto: ' + TX1 + ' Com base no texto, julgue o item: o autor defende que a finalidade principal da fiscalização eletrônica é preventiva, contrapondo-se à crítica de que ela teria caráter meramente arrecadatório.',
      'Correto. Para resolver itens de interpretação, siga o "fio" da argumentação do texto pelos conectores.\n1º período: apresenta a crítica de outras pessoas ("costuma ser criticada como mecanismo arrecadatório"). Note que não é a opinião do autor.\n2º período: "Contudo" (adversativo) marca a virada; o autor traz dados que contrariam a crítica (redução de acidentes).\n3º período: "portanto" (conclusivo) traz a tese do autor, que a finalidade "não é multar, mas induzir o condutor a respeitar o limite", ou seja, prevenir.\nDica de prova: textos argumentativos frequentemente começam com a opinião contrária para depois refutá-la. Identifique quem diz o quê.'),
    q(T1, M1, 'E', 'Texto: “Nem toda ultrapassagem perigosa resulta em acidente. Mas basta uma para que famílias inteiras sejam afetadas. Por isso, a prudência deve ser regra, e não exceção, nas rodovias de pista simples.” Infere-se do texto que as ultrapassagens perigosas sempre resultam em acidentes nas rodovias de pista simples.',
      'Errado. O item contraria literalmente a primeira frase do texto: "Nem toda ultrapassagem perigosa resulta em acidente".\n"Nem toda" significa que algumas resultam e outras não. O item troca essa ideia por "sempre resultam", uma generalização que o texto nega.\nO raciocínio do autor é outro: mesmo não sendo certo o acidente, basta UM para causar uma tragédia; por isso, a prudência deve ser constante.\nDica de prova: desconfie de palavras absolutas no item ("sempre", "nunca", "todos", "exclusivamente"). A banca usa muito essa estratégia para extrapolar o texto.'),
    q(T1, M1, 'C', 'Texto: “O cidadão que denuncia uma irregularidade ao poder público não está fazendo um favor ao Estado. Está exercendo um direito e, de certa forma, cumprindo um dever cívico. Sem a participação social, os órgãos de controle enxergam apenas parte da realidade.” De acordo com o texto, a participação da sociedade amplia a capacidade de os órgãos de controle conhecerem as irregularidades.',
      'Correto. O item é uma paráfrase fiel da última frase do texto.\nO autor diz que, "sem a participação social, os órgãos de controle enxergam apenas parte da realidade". Raciocinando ao contrário: com a participação social, eles enxergam mais, isto é, a participação amplia o conhecimento das irregularidades.\nIsso é inferência legítima: não extrapola, apenas reformula o que o texto diz.\nDica de prova: diferencie inferência (conclusão autorizada pelo texto) de extrapolação (ir além do que o texto permite). Aqui é inferência.'),
    q(T1, M1, 'E', 'Texto: ' + TX2 + ' O autor sustenta que o uso do cinto no banco traseiro interessa exclusivamente à segurança do próprio passageiro que o utiliza.',
      'Errado. A conclusão do texto é justamente que o cinto traseiro é "uma proteção coletiva, e não apenas individual".\nO argumento: em uma colisão, o passageiro sem cinto é projetado contra o banco dianteiro e fere quem está à frente. Portanto, o uso do cinto protege também os outros ocupantes.\nO item diz "exclusivamente à segurança do próprio passageiro", contradizendo o texto.\nDica de prova: o advérbio "exclusivamente" é um sinal de alerta. Quase sempre, a banca o usa para restringir indevidamente o que o texto diz.'),
    q(T1, M1, 'C', 'Texto: ' + TX2 + ' No último período, a expressão “Trata-se, portanto,” introduz uma conclusão extraída das informações apresentadas no período anterior.',
      'Correto. "Portanto" é conjunção (conector) conclusiva: introduz uma conclusão tirada do que foi dito antes.\nEncadeamento lógico do texto:\n• Premissa: o ocupante sem cinto pode ser projetado e ferir quem está à frente.\n• Conclusão ("Trata-se, portanto,"): logo, o cinto é proteção coletiva.\nOutros conectores conclusivos que podem substituí-lo: logo, por isso, por conseguinte, assim, dessa forma, pois (quando posposto ao verbo).\nObservação: "portanto" aparece entre vírgulas porque está deslocado no meio da oração.'),
    q(T1, M1, 'E', 'Texto: ' + TX3 + ' O texto conclui que uma sinalização adequada torna dispensável a atenção do motorista.',
      'Errado. O item afirma o oposto do que o texto conclui.\nOs dois primeiros períodos elogiam a boa sinalização (reduz incerteza, permite decisões seguras). Mas o último traz uma ressalva decisiva: "Ainda assim, nenhuma sinalização substitui a atenção de quem dirige".\nLogo, a sinalização é útil, mas NÃO torna a atenção dispensável.\nDica de prova: a conclusão de um texto costuma vir após conectores como "ainda assim", "contudo", "portanto". Dê atenção especial à última frase.'),
    q(T1, M1, 'C', 'Texto: ' + TX3 + ' No texto, a expressão “Ainda assim” introduz uma ressalva às vantagens da sinalização descritas nos períodos anteriores.',
      'Correto. "Ainda assim" é uma expressão de valor concessivo/adversativo. Equivale a "mesmo assim", "apesar disso", "não obstante".\nEla reconhece o que foi dito antes (as vantagens da sinalização), mas introduz uma limitação: a sinalização não substitui a atenção do motorista.\nIsso é o que chamamos de ressalva: admite-se um argumento, mas aponta-se seu limite.\nPossíveis substituições sem alteração de sentido: "Mesmo assim", "Apesar disso", "Contudo".'),
    q(T1, M1, 'E', 'Texto: ' + TX4 + ' Segundo o texto, os prejuízos decorrentes da interdição de uma ponte restringem-se ao trânsito da localidade em que ela se situa.',
      'Errado. O texto diz expressamente que "os efeitos ultrapassam o trânsito local".\nEm seguida, os dois-pontos detalham esses efeitos: atrasar entregas, encarecer fretes e afetar o abastecimento de cidades DISTANTES. Ou seja, os prejuízos vão muito além da localidade da ponte.\nO item usa "restringem-se", sentido contrário ao de "ultrapassam".\nDica de prova: compare os verbos do item com os do texto. Trocar "ultrapassar" por "restringir-se" inverte o sentido.'),
    q(T1, M1, 'C', 'Texto: ' + TX4 + ' No segundo período, os dois-pontos introduzem uma enumeração que especifica os efeitos mencionados anteriormente.',
      'Correto. Os dois-pontos têm, entre outras, a função de introduzir enumeração, explicação ou especificação de algo dito antes.\nNo texto, o autor primeiro faz uma afirmação genérica ("os efeitos ultrapassam o trânsito local") e, após os dois-pontos, especifica quais são esses efeitos: atrasam entregas, encarecem fretes e afetam o abastecimento.\nFunções dos dois-pontos para a prova: introduzir enumeração; introduzir explicação, síntese ou consequência; introduzir citação ou fala.'),
    q(T1, M1, 'E', 'Texto: “Campanhas educativas produzem resultados lentos, mas duradouros. A punição, por sua vez, tende a gerar efeitos imediatos, que se enfraquecem quando a fiscalização diminui. Políticas eficazes de segurança viária costumam combinar as duas estratégias.” O texto apresenta a punição como estratégia superior às campanhas educativas, a ponto de dever substituí-las.',
      'Errado. O texto não hierarquiza as estratégias; ele as compara de forma equilibrada.\n• Campanhas educativas: resultados lentos, MAS duradouros.\n• Punição: efeitos imediatos, que se enfraquecem quando a fiscalização diminui.\n• Conclusão: políticas eficazes "costumam combinar as duas estratégias".\nO item afirma que a punição é superior e deveria substituir as campanhas, o que contraria a conclusão de que ambas se complementam.\nDica de prova: quando o texto aponta vantagens e desvantagens de duas opções e conclui pela combinação, desconfie de itens que afirmam a superioridade de uma delas.'),

    /* ===== 2 Tipos e gêneros textuais ===== */
    q(T2, M2, 'C', 'No trecho “Ao avistar a viatura, o motorista reduziu a velocidade, estacionou no acostamento e aguardou a abordagem.”, predomina a tipologia narrativa, marcada pela sucessão de ações no tempo.',
      'Correto. A tipologia narrativa se caracteriza pela sucessão de ações no tempo: há um "antes" e um "depois", com progressão dos fatos.\nNo trecho, as ações se encadeiam em ordem cronológica: o motorista avistou → reduziu → estacionou → aguardou. Os verbos estão no pretérito perfeito, tempo típico da narração de fatos concluídos.\nElementos típicos da narração: personagens (o motorista), ações sequenciais, marcação temporal, verbos de ação no passado.\nDica: se dá para perguntar "e depois, o que aconteceu?", provavelmente é narração.'),
    q(T2, M2, 'E', 'No trecho “Reduza a velocidade. Mantenha distância segura do veículo à frente. Em caso de neblina, acenda os faróis baixos.”, predomina a tipologia descritiva.',
      'Errado. A tipologia que predomina é a injuntiva (ou instrucional), e não a descritiva.\nMarca principal da injunção: verbos no modo imperativo que orientam ou instruem o leitor sobre como agir. No trecho: "Reduza", "Mantenha", "acenda".\nA descrição caracteriza seres, objetos ou espaços (cor, forma, tamanho), geralmente com verbos de estado ("é", "tem", "parece") e muitos adjetivos.\nGêneros tipicamente injuntivos: manuais, receitas, bulas (posologia), regulamentos, placas de orientação.'),
    q(T2, M2, 'C', 'No trecho “O posto policial tem fachada branca, janelas amplas e um pátio cercado por grades azuis.”, predomina a tipologia descritiva, voltada à caracterização de um espaço.',
      'Correto. Descrever é caracterizar, ou seja, construir um "retrato" de um ser, objeto ou lugar.\nNo trecho, atribuem-se características ao posto policial: fachada branca, janelas amplas, pátio cercado por grades azuis. Não há progressão de ações no tempo.\nMarcas da descrição: verbo de estado ou de posse ("tem"), adjetivos (branca, amplas, azuis), enumeração de características, ausência de sequência temporal.\nComparação útil: a narração "anda" no tempo; a descrição "congela" a cena.'),
    q(T2, M2, 'E', 'O artigo de opinião é gênero textual em que predomina a tipologia injuntiva, uma vez que seu propósito central é ensinar o leitor a executar procedimentos.',
      'Errado. No artigo de opinião predomina a tipologia argumentativa (dissertativo-argumentativa).\nO propósito do gênero é defender um ponto de vista, convencer o leitor por meio de argumentos (dados, exemplos, relações de causa e consequência).\nA tipologia injuntiva tem outro propósito: orientar o leitor a executar procedimentos. Ela predomina em manuais, receitas, tutoriais e instruções.\nDica de prova: pergunte-se "qual é a intenção principal do texto?". Convencer é argumentação; instruir é injunção; informar é exposição; contar é narração; caracterizar é descrição.'),
    q(T2, M2, 'C', 'Os tipos textuais formam um conjunto limitado de sequências (como narração, descrição, exposição, argumentação e injunção), ao passo que os gêneros textuais são numerosos e definidos por sua função social e situação de uso.',
      'Correto. Essa distinção entre tipo e gênero é uma das mais cobradas pelo Cebraspe.\nTIPOS textuais são modos de organizar a linguagem, em número limitado: narração, descrição, exposição, argumentação e injunção. São definidos por traços linguísticos (tempos verbais, conectores etc.).\nGÊNEROS textuais são os textos concretos que circulam na sociedade, em número praticamente ilimitado: notícia, ofício, e-mail, receita, crônica, bula, edital, boletim de ocorrência... São definidos pela função social e pela situação de uso.\nResumindo: o tipo é a "estrutura"; o gênero é o "texto da vida real".'),
    q(T2, M2, 'E', 'Um gênero textual apresenta sempre um único tipo textual, sendo impossível, por exemplo, a ocorrência de trechos descritivos em uma notícia.',
      'Errado. Os gêneros textuais costumam ser heterogêneos: combinam vários tipos, com predomínio de um deles.\nUma notícia, por exemplo, é predominantemente narrativa/expositiva, mas pode descrever o local de um acidente (descrição) ou trazer a fala de uma autoridade com opinião (argumentação).\nPor isso falamos em tipologia "predominante", e não "exclusiva".\nDica de prova: itens com "sempre", "único" ou "impossível" sobre tipos e gêneros costumam estar errados, justamente pela heterogeneidade tipológica dos gêneros.'),
    q(T2, M2, 'C', 'O trecho “Segundo dados divulgados ontem pelo órgão, o número de acidentes no feriado caiu 12% em relação ao ano anterior.” é compatível com o gênero notícia, cujo propósito é predominantemente informativo.',
      'Correto. O trecho tem todas as marcas do gênero notícia:\n• Indicação de fonte ("Segundo dados divulgados ... pelo órgão"), que dá credibilidade.\n• Marcação temporal ("ontem", "no feriado", "em relação ao ano anterior").\n• Dado objetivo e verificável ("caiu 12%").\n• Linguagem impessoal, em 3ª pessoa, sem opinião explícita do autor.\nO propósito comunicativo da notícia é informar sobre um fato recente, de interesse público, com objetividade.'),
    q(T2, M2, 'E', 'O edital de concurso público é gênero da esfera literária, caracterizado pelo predomínio da linguagem conotativa e pela liberdade de forma.',
      'Errado. O edital pertence à esfera administrativa/jurídica, e não à literária.\nCaracterísticas do edital: linguagem denotativa (sentido literal, sem ambiguidade), objetividade, impessoalidade, estrutura padronizada (itens numerados, capítulos) e finalidade normativa, ou seja, estabelecer regras do concurso.\nA linguagem conotativa (figurada) e a liberdade formal são marcas de gêneros literários, como poema, conto e romance.\nDica de prova: documentos oficiais (edital, ofício, portaria, decreto) seguem a norma-padrão, a clareza e a impessoalidade, princípios da redação oficial.'),
    q(T2, M2, 'C', 'No trecho “O excesso de velocidade é uma das principais causas de mortes no trânsito, pois reduz o tempo de reação e aumenta a gravidade dos impactos.”, a conjunção “pois” introduz justificativa para a afirmação inicial, recurso típico das sequências dissertativas.',
      'Correto. O trecho tem estrutura típica da dissertação: uma tese seguida de sua fundamentação.\n• Afirmação: "O excesso de velocidade é uma das principais causas de mortes no trânsito".\n• Justificativa, introduzida por "pois": "reduz o tempo de reação e aumenta a gravidade dos impactos".\n"Pois", ANTEPOSTO ao verbo, tem valor explicativo/causal (= porque, já que). Se viesse POSPOSTO ao verbo e entre vírgulas, teria valor conclusivo ("É perigoso; deve, pois, ser evitado").\nDica de prova: a posição do "pois" muda seu valor. Fique de olho!'),
    q(T2, M2, 'E', 'A crônica é gênero exclusivamente narrativo, não admitindo reflexões nem comentários do autor acerca de fatos do cotidiano.',
      'Errado. A crônica é um gênero híbrido, e não exclusivamente narrativo.\nEla parte geralmente de um fato do cotidiano (narração), pode descrever ambientes e pessoas (descrição) e quase sempre traz reflexões, comentários e impressões pessoais do autor (argumentação, subjetividade).\nEssa marca reflexiva e pessoal é, aliás, um dos traços mais característicos do gênero, com tom leve, linguagem próxima da oralidade e publicação em jornais e revistas.\nDica de prova: "exclusivamente" e "não admitindo" são exageros típicos de itens errados.'),

    /* ===== 3 Ortografia oficial ===== */
    q(T3, M3, 'C', 'No trecho “A equipe determinou a paralisação parcial da rodovia para a retirada dos veículos.”, a palavra “paralisação” está corretamente grafada com “s”, por derivar do verbo “paralisar”.',
      'Correto. A palavra "paralisação" é escrita com "s" porque pertence à família de "paralisia" e "paralisar", que já têm "s" no radical.\nRegra prática: se a palavra primitiva tem "s", as derivadas mantêm o "s": paralisia → paralisar → paralisação; análise → analisar; pesquisa → pesquisar.\nJá os verbos terminados em "-izar" sem "s" no radical usam "z": real → realizar; final → finalizar; ameno → amenizar.\nEntão "paralização", com "z", é grafia incorreta, e cai muito em prova!'),
    q(T3, M3, 'E', 'No trecho “O condutor tentou impedir a apreensão do veículo.”, a norma ortográfica exigiria a grafia “apreenção”.',
      'Errado. A grafia correta é "apreensão", com "s".\nRegra: verbos terminados em "-ender" e "-ndir" formam substantivos com "-ensão" (com "s"):\napreender → apreensão; compreender → compreensão; suspender → suspensão; pretender → pretensão; expandir → expansão.\nCompare com verbos em "-ter", que formam "-tenção" (com "ç"): deter → detenção; reter → retenção; conter → contenção; manter → manutenção.\nDica: "apreensão de veículo" e "detenção do suspeito" são ótimos pares para lembrar a diferença.'),
    q(T3, M3, 'C', 'No trecho “O candidato matriculou-se em uma autoescola para obter a habilitação.”, a palavra “autoescola” está grafada de acordo com o Acordo Ortográfico vigente.',
      'Correto. Pelo Acordo Ortográfico de 1990, NÃO se usa hífen quando o prefixo termina em vogal e o segundo elemento começa por vogal DIFERENTE.\n"Auto" termina em "o" e "escola" começa com "e". São vogais diferentes, então tudo se escreve junto: autoescola.\nOutros exemplos: autoestrada, infraestrutura, extraoficial, semiaberto, antiaéreo.\nResumo da regra das vogais: vogais IGUAIS → hífen (micro-ondas, anti-inflamatório); vogais DIFERENTES → junto (autoescola, infraestrutura).'),
    q(T3, M3, 'E', 'De acordo com o Acordo Ortográfico vigente, a palavra “micro-ônibus” deve ser grafada sem hífen (“microônibus”), pois o prefixo termina em vogal.',
      'Errado. A regra do Acordo é: usa-se hífen quando o prefixo termina com a MESMA vogal com que começa o segundo elemento.\n"Micro" termina em "o" e "ônibus" começa com "o". São vogais iguais, então há hífen: micro-ônibus.\nOutros exemplos: micro-ondas, anti-inflamatório, contra-ataque, arqui-inimigo, semi-integral.\nO item erra ao generalizar "prefixo terminado em vogal = sem hífen". Isso só vale quando as vogais são diferentes (autoescola, infraestrutura).\nDica: o hífen separa vogais iguais para facilitar a leitura.'),
    q(T3, M3, 'C', 'No trecho “O órgão adotou políticas antirracistas no atendimento ao público.”, a palavra “antirracistas” está corretamente grafada, pois, quando o prefixo termina em vogal e o segundo elemento começa por “r” ou “s”, essas consoantes são duplicadas.',
      'Correto. Pelo Acordo Ortográfico, quando o prefixo termina em vogal e o segundo elemento começa por "r" ou "s", junta-se tudo SEM hífen e DOBRA-SE a consoante.\nanti + racista → antirracista; anti + social → antissocial; contra + regra → contrarregra; ultra + som → ultrassom; mini + saia → minissaia.\nPor que dobrar? Para manter o som forte do "r" e o som de "s" (e não de "z") entre vogais.\nExceção a lembrar: se o prefixo terminar em "r" e o segundo elemento começar com "r", há hífen: inter-regional, super-resistente.'),
    q(T3, M3, 'E', 'No trecho “Com a neblina, o motorista não conseguia enchergar a faixa.”, a grafia do verbo está de acordo com a norma ortográfica.',
      'Errado. A grafia correta é "enxergar", com "x".\nRegra geral: depois da sílaba inicial "en-", usa-se "x": enxergar, enxurrada, enxame, enxada, enxaqueca, enxoval.\nExceção: palavras derivadas de outras que já têm "ch" mantêm o "ch": encher (de cheio), encharcar (de charco), enchumaçar (de chumaço).\n"Enxergar" não deriva de palavra com "ch". Logo, usa-se "x".'),
    q(T3, M3, 'C', 'Com o Acordo Ortográfico vigente, palavras paroxítonas como “ideia” e “assembleia” deixaram de receber acento agudo no ditongo aberto “ei”.',
      'Correto. O Acordo Ortográfico eliminou o acento agudo dos ditongos abertos "ei" e "oi" nas palavras PAROXÍTONAS.\nExemplos: ideia (antes, idéia), assembleia, plateia, europeia, jiboia, heroico, paranoico.\nAtenção: o acento CONTINUA nas oxítonas e monossílabos tônicos terminados nesses ditongos: papéis, anéis, herói, dói, chapéu, réu.\nDica para não errar: se a sílaba tônica é a penúltima (paroxítona), sem acento: i-DEI-a. Se é a última (oxítona), com acento: pa-PÉIS.'),
    q(T3, M3, 'E', 'Com o Acordo Ortográfico vigente, as formas verbais “veem” e “leem” passaram a ser grafadas “vêem” e “lêem”.',
      'Errado. O Acordo fez exatamente o contrário: aboliu o circunflexo nas formas verbais com "ee".\nAntes do Acordo: vêem, lêem, crêem, dêem. Depois do Acordo (vigente): veem, leem, creem, deem.\nNão confunda com o acento que distingue singular e plural dos verbos "ter" e "vir" (e derivados), que continua: ele tem / eles têm; ele vem / eles vêm; ele mantém / eles mantêm.\nDica: "eles veem" (ver) é diferente de "eles vêm" (vir). O primeiro tem dois "e"; o segundo, um só com circunflexo.'),
    q(T3, M3, 'C', 'No trecho “É preciso pôr fim à impunidade no trânsito.”, o acento em “pôr” é mantido pelo Acordo Ortográfico vigente para distinguir o verbo da preposição “por”.',
      'Correto. O acento diferencial foi abolido na maioria dos casos, mas o Acordo manteve alguns, e "pôr" é um deles.\nAcentos diferenciais mantidos:\n• pôr (verbo) × por (preposição): "É preciso pôr fim..."\n• pôde (pretérito perfeito) × pode (presente): "Ontem ele não pôde vir."\n• têm/vêm (plural) × tem/vem (singular).\nAcentos diferenciais abolidos: para (verbo) × para (preposição), pelo (substantivo) × pelo (contração), pera, polo.\nDica: no trecho, "pôr fim" = "acabar com", logo é o verbo pôr, com acento.'),
    q(T3, M3, 'E', 'Pelo Acordo Ortográfico vigente, a forma verbal “pára” continua acentuada para diferenciá-la da preposição “para”, como em “O caminhão pára no posto de pesagem”.',
      'Errado. O acento diferencial de "pára" (verbo parar) foi ABOLIDO pelo Acordo Ortográfico.\nGrafia correta hoje: "O caminhão para no posto de pesagem". O contexto resolve a ambiguidade com a preposição "para".\nMuita gente ainda escreve "pára" por hábito antigo, e por isso a banca cobra esse ponto.\nRevisão rápida dos diferenciais: mantidos em pôr e pôde (e têm/vêm); abolidos em para, pelo, pela, polo, pera.'),

    /* ===== 4.1 Referenciação, substituição, repetição e conectores ===== */
    q(T41, M4, 'C', 'No trecho “Os agentes interceptaram o caminhão na rodovia. O veículo transportava carga sem nota fiscal.”, a expressão “O veículo” retoma “o caminhão” por meio de um hiperônimo.',
      'Correto. Este é um caso de coesão referencial por substituição lexical, usando um hiperônimo.\n• Hiperônimo: palavra de sentido mais geral (veículo).\n• Hipônimo: palavra de sentido mais específico, incluída no hiperônimo (caminhão, carro, moto).\n"Todo caminhão é um veículo, mas nem todo veículo é um caminhão." Ao retomar "o caminhão" por "O veículo", o autor evita a repetição e mantém a referência.\nOutros exemplos: "o cão... o animal"; "a rodovia BR-116... a estrada"; "o fuzil... a arma".'),
    q(T41, M4, 'E', 'No trecho “A condutora apresentou os documentos ao policial, que os conferiu atentamente.”, o pronome “os” retoma “policial”.',
      'Errado. Para descobrir o referente de um pronome, pergunte: "o que foi conferido?". A resposta é "os documentos".\n• "os" é pronome oblíquo, objeto direto de "conferiu", e retoma "os documentos" (masculino plural, mesmo gênero e número).\n• "que" é pronome relativo, retoma "o policial" e funciona como sujeito de "conferiu" (o policial conferiu os documentos).\nNote também a concordância: "os" é plural; "policial" é singular. A retomada sugerida pelo item é incompatível até no número.\nDica: confira gênero e número entre pronome e referente. Isso elimina muitas opções.'),
    q(T41, M4, 'C', 'No trecho “A rodovia estava interditada; por conseguinte, os motoristas tiveram de usar um desvio.”, a substituição de “por conseguinte” por “portanto” preservaria a correção gramatical e o sentido original.',
      'Correto. "Por conseguinte" e "portanto" pertencem ao mesmo grupo: são conectores conclusivos.\nAmbos introduzem uma consequência/conclusão do que foi dito antes: a interdição (causa) → o uso do desvio (consequência).\nOutros conectores conclusivos intercambiáveis: logo, assim, por isso, então, dessa forma, pois (posposto ao verbo).\nA troca mantém a correção e o sentido; a pontuação (ponto e vírgula antes e vírgula depois) também continua adequada.'),
    q(T41, M4, 'E', 'No trecho “Embora a pista estivesse molhada, o motorista manteve a velocidade elevada.”, a substituição de “Embora” por “Porque” preservaria o sentido original.',
      'Errado. A troca muda completamente o sentido, porque os conectores têm valores diferentes.\n• "Embora" é concessivo: apresenta um fato que DEVERIA impedir a ação, mas não impede. A pista estava molhada (motivo para reduzir), mesmo assim o motorista manteve a velocidade alta.\n• "Porque" é causal: apresentaria a pista molhada como CAUSA de manter a velocidade, o que é ilógico.\nAlém disso, há um problema gramatical: "embora" exige subjuntivo ("estivesse"); "porque" pede indicativo ("estava").\nSubstitutos corretos para "embora": ainda que, mesmo que, conquanto, posto que, se bem que.'),
    q(T41, M4, 'C', 'No trecho “Os policiais chegaram cedo ao local e iniciaram a perícia.”, o sujeito de “iniciaram” não está expresso, mas é recuperável pelo contexto, o que configura coesão por elipse.',
      'Correto. Elipse é a omissão de um termo que pode ser facilmente recuperado pelo contexto.\nNo trecho, o sujeito de "iniciaram" ("Os policiais") não é repetido, mas sabemos quem iniciou a perícia pela desinência verbal (-aram, 3ª pessoa do plural) e pela oração anterior.\nA elipse é um mecanismo de coesão que evita repetições desnecessárias e deixa o texto mais fluido.\nVariação a conhecer: zeugma é a elipse de um termo que já apareceu antes no texto, como aqui. Ex.: "Eu prefiro café; ela, chá" (omite-se "prefere").'),
    q(T41, M4, 'E', 'No trecho “O motorista não apenas excedeu o limite de velocidade, mas também dirigia sem habilitação.”, a correlação “não apenas... mas também” estabelece relação de oposição entre as orações.',
      'Errado. A estrutura correlativa "não apenas... mas também" (ou "não só... como também") tem valor ADITIVO, e não adversativo.\nEla soma informações, dando ênfase à segunda: além de exceder o limite, o motorista ainda dirigia sem habilitação. É uma adição que agrava a situação.\nO "mas" aqui não indica oposição, e esse é o ponto que a banca explora. Ele faz parte da correlação aditiva.\nEquivalência: "O motorista excedeu o limite de velocidade E dirigia sem habilitação."'),
    q(T41, M4, 'C', 'No trecho “O condutor foi autuado, pois transitava pelo acostamento.”, a substituição de “pois” por “uma vez que” preservaria a correção gramatical e o sentido original.',
      'Correto. Ambos os conectores têm valor causal/explicativo: introduzem o motivo da autuação.\n"O condutor foi autuado, pois transitava pelo acostamento" = "O condutor foi autuado, uma vez que transitava pelo acostamento".\nOutros conectores equivalentes: porque, porquanto, já que, visto que, dado que, como (este só no início da frase).\nA vírgula antes do conector se mantém adequada, e o modo verbal (indicativo, "transitava") também.'),
    q(T41, M4, 'E', 'A repetição de palavras é sempre um defeito de coesão textual, devendo ser evitada em qualquer circunstância.',
      'Errado. A repetição NÃO é sempre um defeito. Ela é, inclusive, um dos mecanismos de coesão (coesão por reiteração).\nUsos legítimos da repetição:\n• Ênfase ou efeito expressivo: "Nunca, nunca mais faça isso."\n• Clareza e precisão, especialmente em textos técnicos, jurídicos e normativos, em que um sinônimo poderia gerar ambiguidade.\n• Recurso estilístico (anáfora) em poemas e discursos.\nO que se deve evitar é a repetição DESNECESSÁRIA, que torna o texto cansativo.\nDica de prova: "sempre" e "em qualquer circunstância" são sinais fortes de item errado.'),
    q(T41, M4, 'C', 'No trecho “O agente disse apenas isto: a pista seria liberada em uma hora.”, o pronome “isto” antecipa uma informação apresentada posteriormente no texto, constituindo referência catafórica.',
      'Correto. Existem dois tipos de referência dentro do texto (endófora):\n• Anáfora: o termo retoma algo JÁ DITO. Ex.: "Vi o carro. Ele estava amassado." ("Ele" retoma "carro".)\n• Catáfora: o termo antecipa algo que AINDA SERÁ DITO. Ex.: "O agente disse apenas isto: a pista seria liberada em uma hora."\nNo trecho, "isto" aponta para frente, para a informação que vem após os dois-pontos. É catáfora.\nDica tradicional: "isto/este" tendem a anunciar o que vem a seguir (catáfora); "isso/esse" tendem a retomar o que já foi dito (anáfora).'),
    q(T41, M4, 'E', 'No trecho “A PRF e a Polícia Civil atuaram juntas; esta coordenou a perícia, e aquela, o bloqueio da via.”, o pronome “esta” refere-se à PRF.',
      'Errado. Quando os pronomes demonstrativos retomam dois termos citados antes, a regra é:\n• "este/esta" → o termo mais PRÓXIMO (o último citado): Polícia Civil.\n• "aquele/aquela" → o termo mais DISTANTE (o primeiro citado): PRF.\nReescrevendo: "a Polícia Civil coordenou a perícia, e a PRF, o bloqueio da via."\nNote também a vírgula após "aquela": ela indica a elipse do verbo "coordenou" (zeugma).\nDica: pense na distância. "Esta" está aqui, perto; "aquela" está lá, longe.'),

    /* ===== 4.2 Tempos e modos verbais ===== */
    q(T42, M4, 'C', 'No trecho “Se o motorista respeitasse o limite, o acidente não teria ocorrido.”, a combinação do pretérito imperfeito do subjuntivo com o futuro do pretérito composto expressa hipótese contrária a um fato.',
      'Correto. Este é o chamado período hipotético irreal, que expressa uma hipótese contrária ao que realmente aconteceu.\nEstrutura:\n• Condição: "Se" + pretérito imperfeito do subjuntivo → "Se o motorista respeitasse o limite".\n• Consequência: futuro do pretérito (aqui, composto) → "o acidente não teria ocorrido".\nO sentido implícito é que, na realidade, o motorista NÃO respeitou e o acidente OCORREU.\nCorrelação verbal a memorizar: se + imperfeito do subjuntivo (fizesse) ↔ futuro do pretérito (faria/teria feito); se + futuro do subjuntivo (fizer) ↔ futuro do presente (fará).'),
    q(T42, M4, 'E', 'No trecho “Quando o fiscal chegar, a vistoria começará.”, a forma verbal “chegar” está no infinitivo pessoal.',
      'Errado. "Chegar", nesse contexto, está no futuro do subjuntivo, e não no infinitivo.\nO futuro do subjuntivo é usado em orações que indicam um fato futuro e eventual, introduzidas geralmente por "quando", "se", "enquanto", "logo que", "assim que".\nA confusão acontece porque, nos verbos regulares, as duas formas coincidem (chegar/chegar). O truque é testar com um verbo irregular:\n"Quando o fiscal VIER..." (futuro do subjuntivo) × "para o fiscal VIR" (infinitivo).\n"Quando ele FIZER..." × "para ele FAZER". Se no lugar cabe a forma irregular do subjuntivo, é futuro do subjuntivo.'),
    q(T42, M4, 'C', 'No trecho “Os agentes haviam isolado a área quando a imprensa chegou.”, a locução “haviam isolado” está no pretérito mais-que-perfeito composto do indicativo e indica ação anterior a outra também passada.',
      'Correto. O pretérito mais-que-perfeito indica um fato passado ANTERIOR a outro fato também passado. É "o passado do passado".\nNa linha do tempo do trecho:\n1º) os agentes isolaram a área (haviam isolado);\n2º) a imprensa chegou (chegou).\nFormas do mais-que-perfeito do indicativo:\n• Composta: haver/ter no imperfeito + particípio → "haviam isolado", "tinham isolado".\n• Simples: "isolaram" (forma mais rara, típica da escrita formal; ex.: "dissera", "fizera").'),
    q(T42, M4, 'E', 'No trecho “Apresente seus documentos ao agente.”, a forma verbal “apresente” está no presente do indicativo.',
      'Errado. "Apresente" está no modo IMPERATIVO afirmativo, porque expressa uma ordem/instrução dirigida ao interlocutor.\nComo se forma o imperativo:\n• Para "tu" e "vós", vem do presente do indicativo sem o "s": apresenta (tu), apresentai (vós).\n• Para "você", "nós" e "vocês", vem do presente do SUBJUNTIVO: apresente (você), apresentemos (nós), apresentem (vocês).\nO presente do indicativo seria "ele apresenta", com "a" no final.\nDica: no trecho, há uma ordem dirigida a alguém ("Apresente seus documentos"), o que caracteriza o imperativo.'),
    q(T42, M4, 'C', 'No trecho “Em 1990, o órgão reestrutura seu serviço e amplia a fiscalização nas estradas.”, o emprego do presente do indicativo para relatar fato passado caracteriza o chamado presente histórico.',
      'Correto. Presente histórico (ou narrativo) é o uso do presente do indicativo para relatar fatos que ocorreram no passado.\nNo trecho, a data "Em 1990" mostra que o fato é passado, mas os verbos estão no presente: "reestrutura", "amplia".\nEfeito de sentido: aproxima o fato do leitor, dá vivacidade e dinamismo à narrativa, como se acontecesse diante dos seus olhos. É comum em biografias, linhas do tempo e textos jornalísticos.\nOutros usos do presente: verdades universais ("A água ferve a 100 °C") e futuro próximo ("Amanhã eu viajo").'),
    q(T42, M4, 'E', 'No trecho “Talvez a interdição seja suspensa amanhã.”, a forma “seja” está no presente do indicativo, tempo adequado à expressão de fatos tidos como certos.',
      'Errado. "Seja" está no presente do SUBJUNTIVO, e não do indicativo.\nDiferença entre os modos:\n• Indicativo: exprime certeza, fato real ("A interdição é suspensa").\n• Subjuntivo: exprime dúvida, possibilidade, hipótese, desejo ("Talvez a interdição seja suspensa").\nO advérbio "talvez", anteposto ao verbo, pede o subjuntivo justamente por indicar incerteza.\nFormas do verbo "ser": presente do indicativo → sou, és, é...; presente do subjuntivo → que eu seja, que tu sejas, que ele seja...'),
    q(T42, M4, 'C', 'No trecho “Caso a chuva continue, a rodovia será interditada.”, a substituição de “continue” por “continuar”, mantida a conjunção “Caso”, prejudicaria a correção gramatical.',
      'Correto. Pela norma-padrão, cada conjunção condicional pede um tempo específico do subjuntivo:\n• "Se" → futuro do subjuntivo: "Se a chuva continuar, a rodovia será interditada."\n• "Caso" → presente ou pretérito imperfeito do subjuntivo: "Caso a chuva continue..."; "Caso a chuva continuasse...".\nConstruções como "caso continuar" são frequentes na fala, mas a gramática normativa as considera inadequadas.\nDica: memorize os pares "se continuar" e "caso continue". Errar essa combinação é uma pegadinha clássica de concurso.'),
    q(T42, M4, 'E', 'No trecho “O agente dissera que voltaria ao posto.”, a forma “dissera” está no pretérito imperfeito do indicativo.',
      'Errado. "Dissera" está no pretérito mais-que-perfeito SIMPLES do indicativo, e não no imperfeito.\n• Mais-que-perfeito simples: dissera = tinha dito / havia dito (ação anterior a outra passada).\n• Pretérito imperfeito: dizia (ação habitual ou em curso no passado).\n• Pretérito perfeito: disse (ação concluída).\nMacete: o mais-que-perfeito simples tem a terminação "-ra" com acento tônico na penúltima sílaba (dis-SE-ra, fi-ZE-ra, che-GA-ra). Cuidado para não confundir com o futuro do presente ("dirá", "fará").'),
    q(T42, M4, 'C', 'No trecho “Segundo testemunhas, o motorista estaria embriagado.”, o futuro do pretérito é empregado para indicar incerteza, atribuindo a informação a terceiros sem afirmá-la categoricamente.',
      'Correto. Além de indicar fatos futuros em relação a um passado, o futuro do pretérito tem um importante valor MODALIZADOR: indica incerteza ou informação não confirmada.\n"O motorista estaria embriagado" = há a informação (dita por testemunhas), mas quem escreve não se compromete com sua veracidade.\nEsse uso é muito comum no jornalismo e nos documentos oficiais, para evitar afirmar categoricamente o que ainda não foi comprovado (presunção de inocência, apuração em curso).\nCompare: "o motorista ESTAVA embriagado" (afirmação categórica) × "o motorista ESTARIA embriagado" (informação atribuída a outros).'),
    q(T42, M4, 'E', 'No trecho “Nós vimos ao posto ontem para registrar a ocorrência.”, a forma verbal “vimos” está corretamente empregada como pretérito perfeito do verbo “vir”.',
      'Errado. O verbo "vir" é irregular, e a banca explora a confusão com "ver".\n• Pretérito perfeito de VIR: eu vim, tu vieste, ele veio, nós VIEMOS, vós viestes, eles vieram.\n• Presente de VIR: nós VIMOS ("Nós vimos aqui toda semana").\n• Pretérito perfeito de VER: nós VIMOS ("Nós vimos o acidente ontem").\nComo o trecho fala de um fato passado ("ontem") e do verbo "vir" (vir ao posto), a forma correta é "Nós viemos ao posto ontem".'),

    /* ===== 5.1 Classes de palavras ===== */
    q(T51, M5, 'C', 'No trecho “O agente agiu rápido e conteve o tumulto.”, a palavra “rápido” funciona como advérbio, equivalendo a “rapidamente”.',
      'Correto. Uma mesma palavra pode mudar de classe conforme a função que exerce na frase. Aqui, "rápido", que normalmente é adjetivo, funciona como advérbio.\nComo saber? Veja a quem a palavra se refere. "Rápido" não caracteriza um substantivo (o agente); ele modifica o VERBO "agiu", indicando o MODO da ação (agiu como? rápido). Quem modifica verbo é advérbio.\nProva real: troque por "rapidamente", que é advérbio, e o sentido se mantém.\nConsequência: como advérbio, fica invariável. "Os agentes agiram rápido" (e não "rápidos").\nOutros exemplos de adjetivo adverbializado: "falou alto", "custou caro", "trabalhou duro".'),
    q(T51, M5, 'E', 'No trecho “Os agentes chegaram cedo ao posto.”, a palavra “cedo” é adjetivo que caracteriza o substantivo “agentes”.',
      'Errado. "Cedo" é advérbio de tempo, e não adjetivo.\nFaça a pergunta ao verbo: os agentes chegaram QUANDO? Cedo. A palavra indica a circunstância de tempo em que ocorreu a ação de "chegar", ou seja, modifica o verbo.\nAdjetivo é a palavra que caracteriza um substantivo (agentes cansados, agentes experientes). "Cedo" não atribui qualidade aos agentes.\nProva prática: advérbio não varia. Não existe "agentes cedos".'),
    q(T51, M5, 'C', 'No trecho “O andar do motorista indicava embriaguez.”, o verbo “andar” foi substantivado pela anteposição do artigo.',
      'Correto. Derivação imprópria (ou conversão) é a mudança de classe gramatical de uma palavra sem alteração na sua forma.\nNo trecho, "andar" é originalmente verbo (no infinitivo), mas, precedido do artigo "o", passa a funcionar como substantivo: "o andar" = o modo de andar, a marcha.\nProva: o termo é núcleo do sujeito de "indicava" e pode receber adjetivo: "O andar CAMBALEANTE do motorista...".\nOutros exemplos: "o olhar", "o jantar", "o sim", "o porquê", "um não". O artigo é o grande "substantivador" da língua portuguesa.'),
    q(T51, M5, 'E', 'No trecho “As operações foram bastante eficientes.”, a palavra “bastante” é adjetivo e, por isso, deveria concordar com “eficientes”, assumindo a forma “bastantes”.',
      'Errado. Para saber se "bastante" varia, identifique a palavra que ele modifica.\n• Modificando ADJETIVO, verbo ou advérbio → é ADVÉRBIO (= muito) e não varia: "As operações foram bastante eficientes" (muito eficientes).\n• Acompanhando SUBSTANTIVO → é pronome indefinido/adjetivo (= muitos, suficientes) e varia: "Houve bastantes operações" (muitas operações).\nNo trecho, "bastante" intensifica o adjetivo "eficientes". Logo, é advérbio, e a forma "bastante" está correta.\nMacete: substitua por "muito". Se ficar "muito" (invariável), use "bastante"; se ficar "muitos/muitas", use "bastantes".'),
    q(T51, M5, 'C', 'No trecho “A viatura que estava no pátio foi vistoriada.”, a palavra “que” é pronome relativo, retoma “viatura” e poderia ser substituída por “a qual”.',
      'Correto. O pronome relativo tem duas funções: retoma um termo anterior (o antecedente) e introduz uma oração subordinada adjetiva.\nNo trecho, "que" retoma "viatura" e introduz "que estava no pátio", oração que caracteriza a viatura, como faria um adjetivo.\nTeste infalível: se for possível trocar "que" por "o qual / a qual / os quais / as quais", ele é pronome relativo. "A viatura A QUAL estava no pátio foi vistoriada" funciona, com "a qual" concordando com "viatura" (feminino singular).\nSe não der para trocar, provavelmente é conjunção integrante (ex.: "Disse que viria").'),
    q(T51, M5, 'E', 'No trecho “O motorista saiu do posto, mas logo voltou.”, a palavra “mas” é preposição.',
      'Errado. "Mas" é conjunção coordenativa adversativa, e não preposição.\n• Conjunções ligam ORAÇÕES (ou termos de mesma função) e estabelecem relação de sentido entre elas. Aqui, há oposição/quebra de expectativa: saiu, MAS voltou.\n• Preposições ligam TERMOS, criando relação de dependência entre eles: a, ante, após, até, com, contra, de, desde, em, entre, para, perante, por, sem, sob, sobre, trás.\nNote que no trecho há, sim, uma preposição: "de", em "do posto" (de + o).\nSubstitutos de "mas" com o mesmo valor: porém, contudo, todavia, entretanto, no entanto.'),
    q(T51, M5, 'C', 'No trecho “A motorista estava meio cansada após doze horas ao volante.”, a palavra “meio” é advérbio e, por isso, permanece invariável.',
      'Correto. "Meio" pode ser advérbio ou numeral, e a concordância depende disso.\n• Advérbio (= um pouco, um tanto), modificando adjetivo → INVARIÁVEL: "estava meio cansada", "ficaram meio preocupados".\n• Numeral (= metade), acompanhando substantivo → VARIÁVEL: "meia hora", "meio litro", "meia-noite e meia" (meia hora).\nErro muito comum na fala: "ela está meia cansada". Pela norma-padrão, o correto é "meio cansada".\nTeste: troque por "um pouco". "Estava um pouco cansada" funciona, então é advérbio.'),
    q(T51, M5, 'E', 'No trecho “Ninguém presenciou o acidente.”, a palavra “Ninguém” é advérbio de negação.',
      'Errado. "Ninguém" é pronome indefinido substantivo.\n• Pronome: substitui ou acompanha o substantivo, referindo-se à pessoa do discurso.\n• Indefinido: refere-se a pessoas de modo vago e genérico (alguém, ninguém, todos, outrem, algo, nada).\n• Substantivo: ocupa o lugar do substantivo, sem acompanhá-lo. No trecho, é o próprio sujeito de "presenciou".\nAdvérbio de negação é, por exemplo, "não", que modifica o verbo: "O agente NÃO presenciou o acidente".'),
    q(T51, M5, 'C', 'No trecho “Ela recebeu a notificação e a arquivou.”, a primeira ocorrência de “a” é artigo definido, e a segunda é pronome pessoal oblíquo.',
      'Correto. A palavra "a" pode ter várias classes: artigo, pronome oblíquo, preposição e pronome demonstrativo. Veja a função de cada uma.\n• 1º "a" ("a notificação"): acompanha e determina o substantivo "notificação". É ARTIGO definido.\n• 2º "a" ("a arquivou"): substitui o substantivo "a notificação" e completa o verbo transitivo direto "arquivou" (arquivou o quê? a notificação). É PRONOME pessoal oblíquo átono, com função de objeto direto.\nDica: o artigo sempre vem colado a um substantivo; o pronome oblíquo vem junto do verbo, ocupando o lugar do complemento.'),
    q(T51, M5, 'E', 'No trecho “Os policiais trabalharam muito durante o feriado.”, a palavra “muito” é pronome indefinido e concorda com “policiais”.',
      'Errado. A classe de "muito" depende da palavra que ele acompanha.\n• Modificando VERBO, adjetivo ou advérbio → ADVÉRBIO de intensidade, INVARIÁVEL: "Os policiais trabalharam muito".\n• Acompanhando SUBSTANTIVO → PRONOME indefinido, VARIÁVEL: "Muitos policiais trabalharam".\nNo trecho, "muito" intensifica o verbo "trabalharam" (trabalharam quanto? muito). É advérbio e, portanto, não concorda com "policiais".\nA mesma lógica vale para "pouco", "bastante" e "demais".'),

    /* ===== 5.2 Coordenação ===== */
    q(T52, M5, 'C', 'No período “O motorista reduziu a velocidade, sinalizou e parou no acostamento.”, há orações coordenadas assindéticas e uma oração coordenada sindética aditiva.',
      'Correto. Orações coordenadas são independentes entre si. Classificam-se como:\n• Assindéticas: ligadas sem conjunção, apenas por vírgula ou justaposição.\n• Sindéticas: introduzidas por conjunção (do grego "sýndeton", ligação).\nNo período:\n1) "O motorista reduziu a velocidade" → coordenada assindética.\n2) "sinalizou" → coordenada assindética (separada apenas por vírgula).\n3) "e parou no acostamento" → coordenada sindética ADITIVA (conjunção "e", que soma ações).\nLembre-se: cada verbo (ou locução verbal) corresponde, em regra, a uma oração. Aqui há três verbos, logo três orações.'),
    q(T52, M5, 'E', 'No período “Estude com disciplina, que a aprovação virá.”, a palavra “que” introduz oração coordenada adversativa.',
      'Errado. Neste contexto, "que" equivale a "pois" ou "porque" e introduz uma oração coordenada sindética EXPLICATIVA.\nPista importante: a primeira oração está no IMPERATIVO ("Estude"). Depois de ordem, conselho ou pedido, a oração seguinte costuma explicar o motivo do conselho: estude, POIS a aprovação virá.\nOrações adversativas indicam oposição (mas, porém, contudo), o que não ocorre aqui: estudar e ser aprovado não se opõem.\nOutros exemplos de explicativa após imperativo: "Corra, que o ônibus vai sair"; "Fale baixo, porque o bebê dorme".'),
    q(T52, M5, 'C', 'No período “O condutor não portava a CNH, logo foi impedido de seguir viagem.”, a segunda oração é coordenada sindética conclusiva.',
      'Correto. "Logo" é conjunção coordenativa CONCLUSIVA: introduz uma conclusão ou consequência lógica do que foi dito antes.\nRaciocínio: o condutor não portava a CNH (premissa) → logo, foi impedido de seguir (conclusão).\nConjunções conclusivas: logo, portanto, por isso, por conseguinte, assim, então, pois (posposto ao verbo).\nCuidado: "logo" também pode ser advérbio de tempo (= em seguida, imediatamente): "Ele chegou e logo saiu". Para diferenciar, veja se dá para trocar por "portanto" (conclusivo) ou por "em seguida" (temporal).'),
    q(T52, M5, 'E', 'No período “Ora o agente fiscalizava a pista, ora atendia os usuários.”, as orações são coordenadas sindéticas adversativas.',
      'Errado. A correlação "ora... ora" indica ALTERNÂNCIA de ações. As orações são coordenadas sindéticas ALTERNATIVAS.\nSentido: em alguns momentos, o agente fiscalizava; em outros, atendia os usuários. As ações se revezam, sem oposição entre elas.\nConjunções alternativas: ou... ou; ora... ora; quer... quer; seja... seja; já... já.\nAdversativas expressam oposição/contraste (mas, porém, contudo, todavia, entretanto), o que não é o caso.'),
    q(T52, M5, 'C', 'No período “A rodovia foi duplicada; os acidentes, contudo, continuaram frequentes.”, a segunda oração classifica-se como coordenada sindética adversativa, ainda que a conjunção esteja deslocada para o interior dela.',
      'Correto. As conjunções adversativas, com exceção de "mas", podem mudar de lugar dentro da oração, desde que isoladas por vírgulas, sem perder seu valor.\n"A rodovia foi duplicada; os acidentes, contudo, continuaram frequentes" = "A rodovia foi duplicada; contudo, os acidentes continuaram frequentes".\nA relação de oposição se mantém: a duplicação deveria reduzir os acidentes, mas eles continuaram.\nAtenção: "mas" é a única adversativa que precisa ficar no início da oração. Não se diz "os acidentes, mas, continuaram".'),
    q(T52, M5, 'E', 'As orações coordenadas dependem sintaticamente umas das outras, de modo que cada uma exerce função sintática em relação à oração principal.',
      'Errado. O item descreve, na verdade, as orações SUBORDINADAS.\n• Coordenadas: são sintaticamente INDEPENDENTES. Cada uma tem estrutura completa e nenhuma exerce função sintática na outra. Ex.: "Cheguei e saí."\n• Subordinadas: são DEPENDENTES. Exercem uma função sintática (sujeito, objeto, adjunto adnominal, adjunto adverbial...) em relação à oração principal. Ex.: "É necessário que você venha" (a subordinada é o sujeito).\nAtenção: independência sintática não significa ausência de relação de sentido. As coordenadas se relacionam semanticamente (adição, oposição, conclusão...), só não exercem função uma na outra.'),
    q(T52, M5, 'C', 'No período “O policial advertiu o motorista, mas não o multou.”, a substituição de “mas” por “porém” preservaria a correção gramatical e o sentido original.',
      'Correto. "Mas" e "porém" são conjunções coordenativas ADVERSATIVAS: expressam oposição, contraste ou quebra de expectativa.\nNo trecho, a expectativa era que, após a advertência, viesse a multa. A conjunção mostra que isso não aconteceu.\nTrocando: "O policial advertiu o motorista, porém não o multou." A correção gramatical e o sentido se mantêm.\nOutras adversativas possíveis: contudo, todavia, entretanto, no entanto, não obstante.'),
    q(T52, M5, 'E', 'No período “Chovia muito, portanto a pista estava escorregadia.”, a oração introduzida por “portanto” é coordenada sindética explicativa.',
      'Errado. "Portanto" é conjunção coordenativa CONCLUSIVA, e não explicativa.\nRelação no trecho: chovia muito (causa/premissa) → portanto, a pista estava escorregadia (consequência/conclusão).\nDiferença entre as duas:\n• Explicativa: justifica uma afirmação ou ordem anterior (pois, porque, que). Ex.: "Leve guarda-chuva, pois vai chover."\n• Conclusiva: tira conclusão do que foi dito (logo, portanto, por isso). Ex.: "Choveu; portanto, a pista está molhada."\nDica: a explicativa responde "por quê?"; a conclusiva responde "e daí, qual a consequência?".'),
    q(T52, M5, 'C', 'No período “Ele estudou muito e não foi aprovado.”, a conjunção “e”, embora tipicamente aditiva, assume valor adversativo no contexto.',
      'Correto. A classificação das conjunções depende do sentido no contexto, e não apenas da forma.\n"E" é tipicamente aditivo (soma ideias), mas pode assumir valor ADVERSATIVO quando liga ideias que se contrastam.\nNo trecho, o esperado seria que quem estudou muito fosse aprovado. Como o resultado contraria a expectativa, o "e" equivale a "mas": "Ele estudou muito, MAS não foi aprovado."\nEsse "e adversativo" pode ser precedido de vírgula, justamente para marcar o contraste.\nDica de prova: o Cebraspe adora perguntar sobre o valor semântico dos conectores no contexto. Leia a frase e pergunte qual relação de sentido existe ali.'),
    q(T52, M5, 'E', 'No período “Fique atento à sinalização, pois a pista tem curvas perigosas.”, a oração introduzida por “pois” é coordenada sindética conclusiva.',
      'Errado. O valor do "pois" depende da sua posição:\n• ANTEPOSTO ao verbo (no início da oração) → EXPLICATIVO/causal (= porque): "Fique atento, POIS a pista tem curvas perigosas."\n• POSPOSTO ao verbo, entre vírgulas → CONCLUSIVO (= portanto): "A pista tem curvas; fique, POIS, atento."\nNo trecho, "pois" está no início da oração e justifica o conselho dado no imperativo ("Fique atento"). É coordenada sindética EXPLICATIVA.\nMemorize: "pois" no começo explica; "pois" no meio conclui.'),

    /* ===== 5.3 Subordinação ===== */
    q(T53, M5, 'C', 'No período “É necessário que todos usem o cinto de segurança.”, a oração “que todos usem o cinto de segurança” é subordinada substantiva subjetiva.',
      'Correto. Orações subordinadas substantivas exercem funções típicas de substantivos: sujeito, objeto, complemento nominal, predicativo, aposto.\nNo período, faça a pergunta: O QUE é necessário? "Que todos usem o cinto de segurança". Essa oração é o SUJEITO de "é necessário".\nTeste da substituição: troque a oração por "ISSO": "ISSO é necessário". Se "isso" funcionar como sujeito, a oração é substantiva subjetiva.\nEstrutura típica de subjetivas: verbo de ligação + adjetivo + "que..." ("É necessário que", "É importante que", "É provável que"), ou verbos como "convém", "importa", "parece" + "que...".'),
    q(T53, M5, 'E', 'No período “O agente informou que a pista seria liberada.”, a oração “que a pista seria liberada” é subordinada adjetiva restritiva.',
      'Errado. A oração é subordinada substantiva OBJETIVA DIRETA, e não adjetiva.\nAnálise: "informou" é verbo transitivo direto (quem informa, informa algo). Informou O QUÊ? "que a pista seria liberada". A oração completa o verbo, funcionando como OBJETO DIRETO.\nO "que" aqui é conjunção integrante, e não pronome relativo. Teste: não dá para trocar por "o qual" (não existe "informou o qual a pista..."). E não há antecedente substantivo sendo retomado.\nTeste da substituição: "O agente informou ISSO". Funciona, logo é oração substantiva.'),
    q(T53, M5, 'C', 'No período “Os motoristas que dirigiam embriagados foram autuados.”, a oração adjetiva sem vírgulas indica que apenas parte dos motoristas foi autuada.',
      'Correto. Orações adjetivas podem ser restritivas ou explicativas, e a pontuação faz toda a diferença.\n• Restritiva (SEM vírgulas): restringe, delimita o antecedente. "Os motoristas que dirigiam embriagados foram autuados" significa que apenas os embriagados foram autuados. Havia outros, sóbrios, que não foram.\n• Explicativa (COM vírgulas): acrescenta informação sobre TODO o antecedente. "Os motoristas, que dirigiam embriagados, foram autuados" significa que todos dirigiam embriagados e todos foram autuados.\nEssa diferença de sentido é uma das questões favoritas do Cebraspe!'),
    q(T53, M5, 'E', 'No período “Quando a neblina baixou, a rodovia foi fechada.”, a oração “Quando a neblina baixou” é subordinada adverbial causal.',
      'Errado. "Quando", no trecho, indica TEMPO. A oração é subordinada adverbial TEMPORAL.\nPergunta-teste: a rodovia foi fechada QUANDO? "Quando a neblina baixou". A oração indica o momento em que o fato principal ocorreu.\nOração causal indicaria o motivo e seria introduzida por "porque", "visto que", "já que", "como". Ex.: "COMO a neblina baixou, a rodovia foi fechada."\nNote a sutileza: é possível inferir que a neblina foi a causa, mas o conector "quando" expressa gramaticalmente a ideia de tempo. Em prova, classifique pelo conector.'),
    q(T53, M5, 'C', 'No período “Embora estivesse cansado, o motorista seguiu viagem.”, a oração “Embora estivesse cansado” é subordinada adverbial concessiva.',
      'Correto. A oração subordinada adverbial CONCESSIVA expressa um fato que se opõe à ideia principal, mas não é suficiente para impedi-la.\nNo trecho: o cansaço deveria levar o motorista a parar, mas não impediu que ele seguisse viagem.\nConjunções concessivas: embora, ainda que, mesmo que, conquanto, se bem que, posto que, apesar de que. Em geral, exigem o verbo no SUBJUNTIVO ("estivesse").\nEquivalência com coordenação: "Estava cansado, MAS seguiu viagem." A concessiva e a adversativa expressam ideias próximas, com estruturas sintáticas diferentes.'),
    q(T53, M5, 'E', 'No período “O Brasil, que tem extensa malha rodoviária, depende do transporte por caminhões.”, a oração “que tem extensa malha rodoviária” é subordinada adjetiva restritiva.',
      'Errado. A oração está entre VÍRGULAS, logo é subordinada adjetiva EXPLICATIVA, e não restritiva.\n• Explicativa: acrescenta uma informação acessória sobre o antecedente, geralmente algo já sabido ou genérico, sem delimitá-lo. Há só um Brasil, e ter extensa malha rodoviária é uma característica dele.\n• Restritiva: restringe o antecedente a um subconjunto (e não leva vírgula).\nFaria sentido falar em "o Brasil que tem extensa malha rodoviária" em oposição a outro Brasil? Não. Por isso, com nomes próprios e seres únicos, a adjetiva costuma ser explicativa.\nTeste: a oração explicativa pode ser retirada sem alterar a identificação do antecedente.'),
    q(T53, M5, 'C', 'No período “Tenho certeza de que a operação será um sucesso.”, a oração “de que a operação será um sucesso” é subordinada substantiva completiva nominal.',
      'Correto. A oração subordinada substantiva COMPLETIVA NOMINAL completa o sentido de um NOME (substantivo, adjetivo ou advérbio), e vem regida de preposição.\nNo trecho, o substantivo "certeza" pede complemento: certeza DE quê? "de que a operação será um sucesso".\nDiferença em relação à objetiva indireta: esta completa um VERBO ("Lembrei-me de que..."). A completiva nominal completa um NOME ("Tenho lembrança de que...", "Tenho certeza de que...").\nAtenção: a preposição "de" é obrigatória pela norma-padrão. "Tenho certeza que" é frequente na fala, mas a forma culta é "certeza DE que".'),
    q(T53, M5, 'E', 'No período “Se chover, a operação será adiada.”, a oração “Se chover” é subordinada adverbial final.',
      'Errado. A oração "Se chover" é subordinada adverbial CONDICIONAL.\nEla estabelece uma CONDIÇÃO para que o fato principal aconteça: a operação só será adiada caso chova.\nConjunções condicionais: se, caso, desde que, contanto que, a menos que, salvo se, a não ser que.\nOrações FINAIS exprimem a finalidade, o objetivo da ação principal: "para que", "a fim de que", "que". Ex.: "Adiaram a operação PARA QUE ninguém se arriscasse."\nDica: condição responde "em que caso?"; finalidade responde "para quê?".'),
    q(T53, M5, 'C', 'No período “O motorista estava tão cansado que adormeceu ao volante.”, a oração “que adormeceu ao volante” é subordinada adverbial consecutiva.',
      'Correto. A oração subordinada adverbial CONSECUTIVA expressa a CONSEQUÊNCIA do fato da oração principal.\nEstrutura clássica: intensificador na principal ("tão", "tal", "tanto", "tamanho") + "que" na subordinada.\nNo trecho: o motorista estava TÃO cansado (causa/intensidade) QUE adormeceu ao volante (consequência).\nNão confunda com a comparativa: "tão... quanto/como" compara ("Ele é tão cansado quanto ela"); "tão... que" expressa consequência.'),
    q(T53, M5, 'E', 'No período “Os agentes trabalharam durante a madrugada para que a rodovia fosse liberada.”, a oração “para que a rodovia fosse liberada” é subordinada adverbial causal.',
      'Errado. "Para que" é conjunção FINAL. A oração é subordinada adverbial FINAL, que expressa a finalidade, o objetivo da ação principal.\nPergunta-teste: os agentes trabalharam PARA QUÊ? "Para que a rodovia fosse liberada".\nOração causal indicaria o MOTIVO, aquilo que provocou a ação: "Os agentes trabalharam durante a madrugada PORQUE a rodovia estava interditada."\nRepare na diferença de tempo: a causa vem antes do fato (motivo que já existe); a finalidade aponta para depois (objetivo a ser alcançado).\nConjunções finais: para que, a fim de que, que (= para que).'),

    /* ===== 5.4 Pontuação ===== */
    q(T54, M54, 'C', 'No trecho “Os agentes, após longa negociação, liberaram a pista.”, as vírgulas isolam adjunto adverbial intercalado entre o sujeito e o verbo.',
      'Correto. O adjunto adverbial "após longa negociação" (indica tempo) foi deslocado para o meio da oração, entre o sujeito ("Os agentes") e o verbo ("liberaram").\nQuando um termo se intercala entre sujeito e verbo, ele precisa ser isolado por DUAS vírgulas, uma antes e outra depois.\nErro comum: usar só uma vírgula ("Os agentes, após longa negociação liberaram a pista"). Isso acaba separando o sujeito do verbo, o que é proibido.\nRegra geral: termo intercalado é isolado por vírgulas duplas (ou por travessões ou parênteses).'),
    q(T54, M54, 'E', 'No trecho “Os condutores, devem respeitar a sinalização.”, a vírgula está corretamente empregada para destacar o sujeito.',
      'Errado. Esta é a regra de ouro da pontuação: NÃO se separa o sujeito do seu verbo por vírgula (nem o verbo do seu complemento).\n"Os condutores" é o sujeito de "devem respeitar". A vírgula entre eles quebra a estrutura básica da oração.\nCorreto: "Os condutores devem respeitar a sinalização."\nExceção aparente: se houver um termo INTERCALADO entre sujeito e verbo, usam-se DUAS vírgulas para isolá-lo ("Os condutores, segundo o CTB, devem respeitar a sinalização"). Mas uma vírgula sozinha entre sujeito e verbo é sempre erro.'),
    q(T54, M54, 'C', 'Em “Brasília, 15 de março de 2026.”, a vírgula separa corretamente o nome do lugar da data.',
      'Correto. Em datas de documentos, cartas, ofícios e requerimentos, usa-se vírgula para separar o nome do lugar (topônimo) da data.\nFormato padrão: "Brasília, 15 de março de 2026."\nExplicação gramatical: há uma elipse ("Brasília, [em] 15 de março..."), e a vírgula marca essa separação.\nObservação de redação oficial: o mês é escrito com inicial minúscula e o dia sem zero à esquerda; o ano não leva ponto de milhar (2026, e não 2.026).'),
    q(T54, M54, 'E', 'No trecho “Senhor Diretor, solicito providências quanto à sinalização da via.”, a vírgula após “Diretor” poderia ser suprimida sem prejuízo da correção gramatical.',
      'Errado. "Senhor Diretor" é VOCATIVO, o termo usado para chamar ou interpelar o interlocutor. O vocativo é SEMPRE isolado por vírgula, esteja no início, no meio ou no fim da frase.\nExemplos: "Senhor Diretor, solicito..."; "Solicito, Senhor Diretor, providências..."; "Solicito providências, Senhor Diretor."\nO vocativo não faz parte da estrutura sintática da oração (não é sujeito nem complemento), por isso precisa ser separado.\nAtenção: a vírgula do vocativo é obrigatória e diferencia sentidos, como em "Pedro, chegou o ofício" (falo com Pedro) × "Pedro chegou" (Pedro é o sujeito).'),
    q(T54, M54, 'C', 'No trecho “Os motoristas que excederam o limite foram multados.”, a inserção de vírgulas após “motoristas” e após “limite” manteria a correção gramatical, mas alteraria o sentido do período.',
      'Correto. É a clássica diferença entre oração adjetiva RESTRITIVA e EXPLICATIVA, marcada pelas vírgulas.\n• Sem vírgulas (restritiva): "Os motoristas que excederam o limite foram multados." Só os que excederam foram multados; outros, não.\n• Com vírgulas (explicativa): "Os motoristas, que excederam o limite, foram multados." TODOS os motoristas (do grupo em questão) excederam o limite e TODOS foram multados.\nAs duas versões são gramaticalmente corretas, mas dizem coisas diferentes. Por isso o item fala em correção mantida e sentido alterado.\nEsse tipo de item é muito frequente no Cebraspe: "a inserção de vírgulas manteria a correção, mas alteraria o sentido".'),
    q(T54, M54, 'E', 'No trecho “A PRF fiscaliza as rodovias federais; a polícia militar, as estaduais.”, a vírgula após “militar” é incorreta, pois separa o sujeito de seu complemento.',
      'Errado. A vírgula está correta: ela marca a ELIPSE do verbo "fiscaliza" na segunda oração. Essa omissão de um termo já mencionado chama-se ZEUGMA.\nSem a elipse, a frase seria: "...; a polícia militar FISCALIZA as estaduais."\nA vírgula ocupa o lugar do verbo omitido, sinalizando ao leitor que algo foi suprimido.\nOutros exemplos: "Eu fiscalizo a BR-101; ela, a BR-116." / "Uns preferem o turno da manhã; outros, o da noite."'),
    q(T54, M54, 'C', 'No trecho “Foram apreendidos três itens: documentos falsos, munição e uma arma.”, os dois-pontos introduzem corretamente uma enumeração.',
      'Correto. Os dois-pontos estão adequadamente empregados para introduzir uma ENUMERAÇÃO que especifica os "três itens" anunciados antes.\nUsos dos dois-pontos:\n• Enumeração: "Foram apreendidos três itens: documentos falsos, munição e uma arma."\n• Explicação ou esclarecimento: "O motivo era simples: falta de efetivo."\n• Citação ou discurso direto: "O agente disse: \'Desligue o motor.\'"\n• Síntese ou conclusão do que foi dito.\nNote ainda que, na enumeração, os elementos são separados por vírgulas e o último é ligado por "e".'),
    q(T54, M54, 'E', 'No trecho “O motorista que foi abordado na madrugada, apresentou documento falso.”, a vírgula está corretamente empregada para isolar a oração adjetiva.',
      'Errado. A oração "que foi abordado na madrugada" é adjetiva RESTRITIVA: especifica de qual motorista se fala. Ela faz parte do sujeito.\nSujeito completo: "O motorista que foi abordado na madrugada". Verbo: "apresentou".\nA vírgula após "madrugada" separa o sujeito do verbo, o que é proibido.\nDuas formas corretas:\n• Restritiva (sem vírgulas): "O motorista que foi abordado na madrugada apresentou documento falso."\n• Explicativa (com DUAS vírgulas): "O motorista, que foi abordado na madrugada, apresentou documento falso."\nO que nunca pode é a vírgula sozinha só no fim da oração adjetiva.'),
    q(T54, M54, 'C', 'No trecho “Ontem à noite, a equipe realizou a operação.”, a vírgula após o adjunto adverbial anteposto poderia ser suprimida sem prejuízo da correção gramatical.',
      'Correto. O adjunto adverbial "Ontem à noite" está anteposto (no início da oração, antes do sujeito).\nRegra: quando o adjunto adverbial anteposto é CURTO, a vírgula é FACULTATIVA. Quando é LONGO, a vírgula é recomendada.\n• "Ontem à noite a equipe realizou a operação." (correto)\n• "Ontem à noite, a equipe realizou a operação." (correto)\nAtenção: se o adjunto adverbial estiver INTERCALADO entre sujeito e verbo, as duas vírgulas passam a ser obrigatórias ("A equipe, ontem à noite, realizou...").'),
    q(T54, M54, 'E', 'No trecho “Os agentes apreenderam a carga, e o motorista foi preso.”, a vírgula antes da conjunção “e” está incorreta, pois nunca se emprega vírgula antes dessa conjunção.',
      'Errado. A ideia de que "nunca se usa vírgula antes de \'e\'" é um mito. Há casos em que a vírgula é possível ou até recomendada:\n1) Orações com SUJEITOS DIFERENTES: "Os agentes apreenderam a carga, e o motorista foi preso." (sujeitos: "os agentes" e "o motorista"). É exatamente o caso do trecho.\n2) "E" com valor ADVERSATIVO (= mas): "Estudou muito, e não passou."\n3) "E" repetido (polissíndeto): "E corria, e gritava, e chorava."\n4) "E" com valor de consequência ou ênfase.\nRegra geral: com o MESMO sujeito, normalmente não se usa vírgula antes de "e".'),

    /* ===== 5.5 Concordância verbal e nominal ===== */
    q(T55, M55, 'C', 'No trecho “Havia muitos veículos retidos no pátio.”, o verbo “haver” está corretamente flexionado no singular.',
      'Correto. O verbo "haver" no sentido de EXISTIR (ou de ocorrer, ou indicando tempo decorrido) é IMPESSOAL: não tem sujeito e, por isso, fica sempre na 3ª pessoa do singular.\n"Havia muitos veículos" → "muitos veículos" é OBJETO DIRETO, e não sujeito. Por isso o verbo não concorda com ele.\nErrado: "Haviam muitos veículos."\nAtenção à locução: o verbo auxiliar também fica no singular: "DEVE haver muitos veículos" (e não "devem haver").\nCompare com "existir", que é pessoal e concorda: "Existiam muitos veículos."'),
    q(T55, M55, 'E', 'No trecho “Fazem cinco anos que a rodovia foi duplicada.”, a concordância verbal está de acordo com a norma-padrão.',
      'Errado. O verbo "fazer", quando indica TEMPO DECORRIDO ou fenômeno da natureza, é IMPESSOAL e fica na 3ª pessoa do singular.\nCorreto: "FAZ cinco anos que a rodovia foi duplicada."\n"Cinco anos" não é sujeito, e sim complemento do verbo impessoal; não há com quem concordar.\nMesma regra em locução verbal: "VAI FAZER cinco anos" (e não "vão fazer").\nOutros verbos impessoais: haver (= existir/tempo), chover, nevar, ventar, amanhecer (no sentido próprio).'),
    q(T55, M55, 'C', 'No trecho “Mais de um motorista foi autuado na operação.”, o verbo no singular está de acordo com a norma-padrão.',
      'Correto. Com a expressão "mais de um", o verbo normalmente fica no SINGULAR, concordando com o numeral "um".\n"Mais de um motorista FOI autuado."\nO plural é exigido em dois casos:\n1) Ideia de reciprocidade: "Mais de um motorista se agrediram." (um agrediu o outro)\n2) Expressão repetida: "Mais de um policial, mais de um agente participaram."\nCompare: com "mais de dois", "mais de três" etc., o verbo vai para o plural: "Mais de dois motoristas FORAM autuados."'),
    q(T55, M55, 'E', 'No trecho “É proibido a entrada de pessoas estranhas ao serviço.”, a concordância nominal está de acordo com a norma-padrão.',
      'Errado. A concordância de "é proibido", "é necessário", "é bom" depende de o substantivo estar ou não DETERMINADO (por artigo, pronome etc.).\n• Substantivo COM determinante → o adjetivo CONCORDA: "É proibidA A entrada" (feminino, por causa de "a entrada").\n• Substantivo SEM determinante → o adjetivo fica no masculino singular (invariável): "É proibido entrada."\nNo trecho, "a entrada" tem artigo "a". Portanto, o correto é "É proibida a entrada de pessoas estranhas ao serviço."\nOutros exemplos: "Água é bom para a saúde" × "A água é boa para a saúde"; "É necessário paciência" × "É necessária a paciência".'),
    q(T55, M55, 'C', 'No trecho “Seguem anexos os relatórios da operação.”, o adjetivo “anexos” concorda corretamente com “relatórios”.',
      'Correto. "Anexo" é ADJETIVO e, como todo adjetivo, concorda em gênero e número com o substantivo a que se refere.\n"Seguem anexos os relatórios" (masculino plural, concordando com "relatórios").\nOutros exemplos: "Segue anexa a planilha"; "Seguem anexas as fotografias"; "Segue anexo o documento".\nObservação: a expressão "em anexo" é invariável ("Seguem em anexo os relatórios"), mas alguns gramáticos a evitam em textos oficiais.\nMesma regra vale para "incluso", "apenso", "quite" e "obrigado": todos são adjetivos e variam.'),
    q(T55, M55, 'E', 'No trecho “Faltou dois agentes na escala de hoje.”, a concordância verbal está de acordo com a norma-padrão.',
      'Errado. Quando o sujeito vem DEPOIS do verbo (sujeito posposto), a concordância continua obrigatória. Esse é um dos erros mais frequentes, por isso a banca o cobra tanto.\nPergunte ao verbo: o que faltou? "dois agentes". Esse é o sujeito, no plural.\nCorreto: "FALTARAM dois agentes na escala de hoje."\nTruque: coloque o sujeito na ordem direta, antes do verbo. "Dois agentes faltou" soa errado, então o certo é "Dois agentes faltaram".\nVerbos que costumam aparecer com sujeito posposto: faltar, sobrar, bastar, restar, ocorrer, existir, acontecer.'),
    q(T55, M55, 'C', 'No trecho “A maioria dos motoristas respeitou o limite de velocidade.”, a forma verbal “respeitaram” também seria aceita pela norma-padrão.',
      'Correto. Com expressões PARTITIVAS ("a maioria de", "grande parte de", "metade de", "a maior parte de") seguidas de substantivo no PLURAL, a norma-padrão admite as duas concordâncias:\n• Singular, concordando com o núcleo ("a maioria"): "A maioria dos motoristas respeitou o limite."\n• Plural, concordando com o especificador ("motoristas"): "A maioria dos motoristas respeitaram o limite."\nO singular enfatiza o conjunto; o plural enfatiza os elementos individuais.\nObservação: se o verbo vier antes da expressão, prefere-se o singular.'),
    q(T55, M55, 'E', 'No trecho “Ao final do atendimento, a usuária disse ao agente: muito obrigado.”, a forma “obrigado” está adequada à norma-padrão, já que essa palavra é invariável.',
      'Errado. "Obrigado" é ADJETIVO (vem de "obrigar": quem agradece se sente "obrigado", isto é, em dívida de gratidão). Por isso, concorda com quem fala.\n• Homem: "Muito obrigado."\n• Mulher: "Muito obrigada."\n• Vários homens, ou grupo misto: "Muito obrigados."\n• Várias mulheres: "Muito obrigadas."\nNo trecho, quem fala é "a usuária" (feminino); logo, deveria dizer "muito obrigada".\nMesma regra para "quite", "anexo", "incluso", "mesmo" e "próprio": todos concordam com o termo a que se referem.'),
    q(T55, M55, 'C', 'No trecho “Vendem-se veículos apreendidos em leilão.”, o verbo no plural está correto, pois concorda com o sujeito paciente “veículos apreendidos”.',
      'Correto. Quando o "se" acompanha um verbo TRANSITIVO DIRETO (vender algo), ele é PRONOME APASSIVADOR, e a frase está na voz passiva sintética.\nNa passiva, o termo que "sofre" a ação é o SUJEITO PACIENTE, e o verbo concorda com ele.\n"Vendem-se veículos apreendidos" = "Veículos apreendidos SÃO VENDIDOS" (voz passiva analítica).\nSujeito: "veículos apreendidos" (plural) → verbo no plural: "vendem-se".\nTeste prático: transforme na passiva analítica. Se funcionar, o "se" é apassivador e o verbo concorda.\nOutros exemplos: "Alugam-se casas"; "Consertam-se pneus"; "Fiscalizaram-se os veículos".'),
    q(T55, M55, 'E', 'No trecho “Precisa-se de agentes qualificados.”, a norma-padrão exigiria a forma “Precisam-se”, em concordância com “agentes”.',
      'Errado. Este item é o par do anterior e mostra o outro lado da regra.\n"Precisar DE" é verbo TRANSITIVO INDIRETO (exige preposição). Com esse tipo de verbo, o "se" é ÍNDICE DE INDETERMINAÇÃO DO SUJEITO.\nNesse caso, o sujeito é indeterminado e o verbo fica OBRIGATORIAMENTE no singular. "Agentes qualificados" é OBJETO INDIRETO (vem com preposição "de"), e não sujeito.\nTeste: tente a passiva analítica. "Agentes qualificados são precisados" não funciona. Logo, não há voz passiva.\nResumo: VTD + se → apassivador → concorda ("Vendem-se casas"). VTI/VI/VL + se → índice de indeterminação → singular ("Precisa-se de agentes"; "Confia-se nos agentes"; "Vive-se bem aqui").')
  ]);
})();
